    // 00 > 01 (1) -> false
    // 00 > 10 (2) -> false
    // 01 (1) > 00 (0) -> true
    // 01 > 11 (3) -> false
    // 10 (2) > 00 (0) -> true
    // 10 > 01 (1) -> true
    // 10 > 11 (3) -> false
    // 11 (3) > anything -> false (since max is 3)
    // This correctly models "level rose".
    // If level was 00 (below s[0]) and rises to 01 (between s[1] and s[0]), dfr=1.
