module TopModule (
    input  logic d,
    input  logic done_counting,
    input  logic ack,
    input  logic [9:0] state,
    output logic B3_next,
    output logic S_next,
    output logic S1_next,
    output logic Count_next,
    output logic Wait_next,
    output logic done,
    output logic counting,
    output logic shift_ena
);

    // State encoding: S=1, S1=2, S11=4, S110=8, B0=16, B1=32, B2=64, B3=128, Count=256, Wait=512
    // One-hot: (S, S1, S11, S110, B0, B1, B2, B3, Count, Wait)
    //           (10'b0000000001, 10'b0000000010, ... , 10'b1000000000)

    // --- Next-state decode signals ---
    // S_next: state == S (bit 0 set)
    assign S_next = (state == 10'b0000000001);

    // S1_next: state == S1 (bit 1 set)
    assign S1_next = (state == 10'b0000000010);

    // B3_next: state == B3 (bit 7 set)
    assign B3_next = (state == 10'b1000000000);

    // Count_next: state == Count (bit 8 set)
    assign Count_next = (state == 10'b0100000000);

    // Wait_next: state == Wait (bit 9 set)
    assign Wait_next = (state == 10'b0010000000);

    // --- Output logic (Moore machine) ---
    // done: asserted only in Wait state
    assign done = (state == 10'b0010000000);

    // counting: asserted only in Count state
    assign counting = (state == 10'b0100000000);

    // shift_ena: asserted in B0, B1, B2, B3 states
    // Encoding check: B0=bit4(16), B1=bit5(32), B2=bit6(64), B3=bit7(128)
    // So shift_ena is true when bits 7 down to 4 are all 1.
    assign shift_ena = (state[7:4] == 4'b1111);

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the 3 received bytes
    logic [23:0] shift_reg;

    // FSM state transition logic (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            done      <= 1'b0; // default: de-asserted

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        shift_reg  <= {in, 16'b0}; // byte 1 in MSB
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive byte 2
                    next_state <= BYTE2;
                    shift_reg  <= {shift_reg[15:0], in}; // shift in byte 2
                end

                BYTE2: begin
                    // Receive byte 3
                    next_state <= BYTE3;
                    shift_reg  <= {shift_reg[7:0], in};  // shift in byte 3
                end

                BYTE3: begin
                    // All 3 bytes received; assert done next cycle
                    // out_bytes already holds the valid 24-bit message
                    next_state <= IDLE;
                    done       <= 1'b1;
                end
            endcase
        end
    end

    // Output assignment: out_bytes is valid whenever done is asserted
    // (registered to avoid combinational loops, though out_bytes is
    //  only needed when done is high)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            out_bytes <= 24'b0;
        else if (done)
            out_bytes <= shift_reg;
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT,    // 0
        WALK_RIGHT,   // 1
        FALLING,      // 2
        DIGGING,      // 3
        SPLATTERED    // 4
    } state_t;

    state_t state, next_state;

    // Outputs (Moore machine - outputs depend only on state)
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state <= WALK_LEFT;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            WALK_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall immediately when ground disappears
                    next_state = FALLING;
                end else if (dig) begin
                    // Start digging if told to dig on ground
                    next_state = DIGGING;
                end else if (bump_right) begin
                    // Bumped on right -> walk right
                    next_state = WALK_RIGHT;
                end else if (bump_left) begin
                    // Bumped on left -> walk left (already left, but spec says switch)
                    next_state = WALK_LEFT;
                end
                // If bumped on both sides, right takes precedence in if-else chain,
                // but spec says "still switch directions". Since we're already walking left,
                // walking left is a valid switch. We'll handle both bumps below.
                if (bump_left && bump_right) begin
                    // Bumped on both sides -> switch direction
                    // If walking left, switch to right; if walking right, switch to left
                    // But we're in WALK_LEFT here, so switch to right
                    next_state = WALK_RIGHT;
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                end else if (dig) begin
                    next_state = DIGGING;
                end else if (bump_left) begin
                    next_state = WALK_LEFT;
                end else if (bump_right) begin
                    next_state = WALK_RIGHT;
                end
                if (bump_left && bump_right) begin
                    next_state = WALK_LEFT;
                end
            end

            FALLING: begin
                // Count falling cycles
                // We need to track how long we've been falling
                // If ground appears and we've been falling > 20 cycles -> splatter
                // If ground appears and <= 20 cycles -> resume walking in same direction
                // If ground = 0 still -> keep falling

                // Check if ground has appeared
                if (ground) begin
                    // Ground reappeared
                    // Need to check fall duration - we'll use a counter
                    // For now, assume we need to track cycles fallen
                    // This requires a counter register
                    // Let's handle this in the counter logic
                end
                // If still no ground, stay falling
                // (direction change and dig are ignored while falling)
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached other side, start falling
                    next_state = FALLING;
                end else if (!dig) begin
                    // Stop digging (told to stop, or ground disappeared)
                    // Actually spec: "will continue digging until it reaches the other side (ground=0)"
                    // So if dig goes to 0 while on ground, what happens?
                    // Spec doesn't explicitly say, but likely stop digging and walk
                    next_state = WALK_LEFT; // or keep current direction?
                    // Let's assume if dig=0, stop digging and resume walking
                    // But we need to know which direction...
                end
                // If ground=1 and dig=1, stay digging
            end

            SPLATTERED: begin
                // Stuck here forever until reset
                next_state = SPLATTERED;
            end
        endcase
    end

endmodule

module TopModule (
    input  [2:0] in,
    output [1:0] out
);

    // Population count: count the number of '1's in the 3-bit input.
    // out is 2 bits wide (can represent values 0 to 3).
    assign out = {in[1] + in[2], in[0] + in[1] + in[2]};

endmodule

module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    logic d0, q0, d1, q1, d2, q2;

    // Three D flip-flops. They are reset to zero initially.
    always_ff @(posedge clk) begin
        // FF0: D input is XOR of x and its own output q0
        d0 <= x ^ q0;
        q0 <= d0;

        // FF1: D input is AND of x and complemented output q1
        d1 <= x & ~q1;
        q1 <= d1;

        // FF2: D input is OR of x and complemented output q2
        d2 <= x | ~q2;
        q2 <= d2;
    end

    // Three-input NOR gate: inputs are the three flip-flop outputs q0, q1, q2
    assign z = ~(q0 | q1 | q2);

endmodule

module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // out_both[i] = in[i] & in[i+1]  for i = 0,1,2
    // out_both[3] is not needed (in[3] has no left neighbour)
    assign out_both = {in[2] & in[3], in[1] & in[2], in[0] & in[1], 1'b0};

    // out_any[i] = in[i] | in[i-1]   for i = 1,2,3
    // out_any[0] is not needed (in[0] has no right neighbour)
    assign out_any = {in[3] | in[2], in[2] | in[1], in[1] | in[0], 1'b0};

    // out_different[i] = in[i] ^ in[i-1]  for i = 1,2,3
    // out_different[0] uses wrapping: in[0] ^ in[3]
    assign out_different = {in[3] ^ in[2], in[2] ^ in[1], in[1] ^ in[0], in[0] ^ in[3]};

endmodule

module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

    // State encoding: 0=S0, 1=S1, 2=S2, 3=S3, 4=S_FOUND
    typedef enum logic [2:0] {
        S0 = 3'b000,
        S1 = 3'b001,
        S2 = 3'b010,
        S3 = 3'b011,
        S_FOUND = 3'b100
    } state_type;

    state_type state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            S0: begin
                if (data == 1'b1)
                    next_state = S1;
                else
                    next_state = S0;
            end
            S1: begin
                if (data == 1'b1)
                    next_state = S2;
                else
                    next_state = S0;
            end
            S2: begin
                if (data == 1'b0)
                    next_state = S3;
                else
                    next_state = S1; // overlapping: '1' restarts at S1
            end
            S3: begin
                if (data == 1'b1)
                    next_state = S_FOUND;
                else
                    next_state = S0;
            end
            S_FOUND: begin
                next_state = S_FOUND;
            end
            default: next_state = S0;
        endcase
    end

    // Output logic: start_shifting is 1 only when we have reached the found state
    assign start_shifting = (state == S_FOUND);

endmodule

module TopModule (
    input  a,
